SELECT "member"."firstname", "region"."city", "member"."city", "member"."member_code"
FROM "provider" LEFT JOIN "region" ON "provider"."region_no" = "region"."region_no" JOIN "member" ON "region"."region_no" = "member"."region_no" WHERE "region"."phone_no" = 'default' AND "member"."corp_no" IS NOT NULL AND "provider"."mail_code" != 'default' LIMIT 13;

SELECT "member"."country", "member"."region_no"
FROM "member" WHERE "member"."photograph" = 'default' LIMIT 61;

